<longcat_arg_value>#!/usr/bin/env python3
"""简单的待办事项管理 CLI 工具"""

import json
import os
from datetime import datetime

TODO_FILE = os.path.expanduser("~/.todo_list.json")


def load_todos():
    if os.path.exists(TODO_FILE):
        with open(TODO_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    return []


def save_todos(todos):
    with open(TODO_FILE, "w", encoding="utf-8") as f:
        json.dump(todos, f, ensure_ascii=False, indent=2)


def add_todo(text):
    todos = load_todos()
    todo = {
        "id": len(todos) + 1,
        "text": text,
        "done": False,
        "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }
    todos.append(todo)
    save_todos(todos)
    print(f"✅ 已添加: {text}")


def list_todos():
    todos = load_todos()
    if not todos:
        print("📋 暂无待办事项")
        return
    for todo in todos:
        status = "✅" if todo["done"] else "⬜"
        print(f"  {status} [{todo['id']}] {todo['text']}  ({todo['created_at']})")


def done_todo(todo_id):
    todos = load_todos()
    for todo in todos:
        if todo["id"] == todo_id:
            todo["done"] = True
            save_todos(todos)
            print(f"🎉 已完成: {todo['text']}")
            return
    print(f"❌ 未找到编号为 {todo_id} 的待办事项")


def delete_todo(todo_id):
    todos = load_todos()
    for i, todo in enumerate(todos):
        if todo["id"] == todo_id:
            removed = todos.pop(i)
            for j, t in enumerate(todos):
                t["id"] = j + 1
            save_todos(todos)
            print(f"🗑️ 已删除: {removed['text']}")
            return
    print(f"❌ 未找到编号为 {todo_id} 的待办事项")


def main():
    import sys

    if len(sys.argv) < 2:
        print("用法: todo <命令> [参数]")
        print("  命令:")
        print("    add <内容>    添加待办")
        print("    list          查看所有待办")
        print("    done <编号>   标记完成")
        print("    delete <编号> 删除待办")
        return

    cmd = sys.argv[1]

    if cmd == "add":
        text = " ".join(sys.argv[2:])
        if not text:
            print("❌ 请提供待办内容")
            return
        add_todo(text)
    elif cmd == "list":
        list_todos()
    elif cmd == "done":
        try:
            done_todo(int(sys.argv[2]))
        except (IndexError, ValueError):
            print("❌ 请提供有效的编号")
    elif cmd == "delete":
        try:
            delete_todo(int(sys.argv[2]))
        except (IndexError, ValueError):
            print("❌ 请提供有效的编号")
    else:
        print(f"❌ 未知命令: {cmd}")


if __name__ == "__main__":
    main()
